#!/usr/bin/env bash
set -euo pipefail
GSZ=/opt/gsz
TS=$(date +%Y%m%d-%H%M%S)
BK="$GSZ/.bak-step163-$TS"
echo "==> step163: Free IPTV Trial button + live modal engine (#4)"
echo "    backup: $BK"
mkdir -p "$BK/routes" "$BK/views/partials"
cp "$GSZ/routes/trials.js"                  "$BK/routes/"          2>/dev/null || true
cp "$GSZ/views/partials/store_bottom.ejs"   "$BK/views/partials/"  2>/dev/null || true
cp "$GSZ/views/partials/store_top.ejs"      "$BK/views/partials/"  2>/dev/null || true
cp "$GSZ/views/home.ejs"                     "$BK/views/"           2>/dev/null || true

restore(){ echo "!! error — restoring"; cp "$BK/routes/trials.js" "$GSZ/routes/" 2>/dev/null || true; cp "$BK/views/partials/store_bottom.ejs" "$GSZ/views/partials/" 2>/dev/null || true; cp "$BK/views/partials/store_top.ejs" "$GSZ/views/partials/" 2>/dev/null || true; cp "$BK/views/home.ejs" "$GSZ/views/" 2>/dev/null || true; }
trap 'restore' ERR

PATCHER=$(mktemp /tmp/patch_step163.XXXXXX.js)
echo "" | base64 -d > "$PATCHER"
echo "==> applying"
NODE_PATH="$GSZ/node_modules" node "$PATCHER" "$GSZ"

echo "==> validating"
node --check "$GSZ/routes/trials.js"
for v in views/partials/store_bottom.ejs views/partials/store_top.ejs views/home.ejs; do
  NODE_PATH="$GSZ/node_modules" node -e "const ejs=require('ejs'),fs=require('fs');ejs.compile(fs.readFileSync('$GSZ/'+'$v','utf8'),{filename:'$GSZ/'+'$v'});"
done
echo "    node --check + ejs ok"

echo "==> restarting"
pm2 restart gsz >/dev/null 2>&1 || pm2 restart gsz
CODE=000
for i in $(seq 1 25); do sleep 1; CODE=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/ || echo 000); [ "$CODE" = "200" ] && break; done
[ "$CODE" = "200" ] || { echo "    homepage $CODE after ${i}s"; false; }
echo "    homepage 200: OK (after ${i}s)"
# sanity: /api/trials responds
TJ=$(curl -s http://127.0.0.1:3900/api/trials || echo '')
echo "$TJ" | grep -q '"ok"' && echo "    /api/trials: responding" || echo "    /api/trials: (no ok yet — check trial_servers has enabled rows)"

rm -f "$PATCHER"
trap - ERR
echo ""
echo "==> step163 OK  'Free IPTV Trial' button now in the header + a home hero banner. It opens a live modal listing your bot trials with remaining quota; Claim enforces sign-in + WhatsApp and sends the trial to the customer's WhatsApp. Hard-refresh once."
